    self.installHint = try c.decode(String.self, forKey: .installHint)
    self.detail = try c.decodeWireOption(String.self, forKey: .detail)
  }

  public func encode(to encoder: any Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(kind, forKey: .kind)
    try c.encode(implemented, forKey: .implemented)
    try c.encode(label, forKey: .label)
    try c.encodeIfPresent(executable, forKey: .executable)
    try c.encode(status, forKey: .status)
    try c.encodeWireOption(version, forKey: .version)
    try c.encode(installHint, forKey: .installHint)
    try c.encodeWireOption(detail, forKey: .detail)
  }
}
